settings.custom_css:
/* RAMIS CHECKOUT — OPTIMIZED */

.woocommerce-checkout{
    --primary:#006660;
    --primary-dark:#004F4B;
    --primary-soft:#EAF4F3;
    --yellow:#FFCE3A;
    --yellow-soft:#FFF8E7;
    --bg:#F5F6F7;
    --card:#fff;
    --border:#E3E6E8;
    --text:#1B252C;
    --muted:#7C858C;
    --radius:8px;

    direction:rtl;
    background:var(--bg);
    color:var(--text);
    font-family:"Yekan Bakh",sans-serif!important;
}

.woocommerce-checkout *,
.woocommerce-checkout input,
.woocommerce-checkout select,
.woocommerce-checkout textarea,
.woocommerce-checkout button{
    font-family:"Yekan Bakh",sans-serif!important;
}

/* MAIN GRID */
form.checkout.woocommerce-checkout{
    max-width:1180px;
    margin:40px auto;
    display:grid;
    grid-template-columns:minmax(0,.72fr) minmax(0,1.28fr);
    grid-template-areas:"summary customer";
    gap:24px;
    align-items:start;
}

/* CUSTOMER */
#customer_details{
    grid-area:customer;
    width:100%;
    margin:0!important;
    padding:0!important;
}

#customer_details .col-1,
#customer_details .col-2,
.woocommerce-billing-fields__field-wrapper .form-row{
    width:100%!important;
    float:none!important;
    margin:0!important;
    padding:0!important;
}

/* CARDS */
.woocommerce-billing-fields,
.woocommerce-checkout-review-order-table,
#payment{
    background:var(--card);
    border-radius:var(--radius);
    box-shadow:0 4px 6px rgba(0,0,0,.06);
}

.woocommerce-billing-fields{
    padding:28px;
    margin:0!important;
}

/* TITLES */
.woocommerce-billing-fields>h3,
#order_payment_heading,
#order_review_heading{
    display:none!important;
}

.checkout-titles{
    margin-bottom:22px;
}

#payment .checkout-titles{
    margin-bottom:20px;
}

.checkout-titles h3{
    display:flex;
    align-items:center;
    gap:10px;
    margin:0!important;
    color:var(--primary);
    font-size:18px;
    font-weight:800;
}

.checkout-titles h3::before{
    content:"♙";
    display:grid;
    place-items:center;
    width:30px;
    height:30px;
    flex:none;
    border-radius:50%;
    background:var(--primary-soft);
    color:var(--primary);
    font-size:15px;
}

/* BILLING FIELDS */
.woocommerce-billing-fields__field-wrapper{
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:17px 14px;
}

.woocommerce-billing-fields__field-wrapper .form-row-wide{
    grid-column:1/-1;
}

/* LABELS */
.woocommerce-checkout label{
    display:block;
    margin-bottom:8px;
    color:var(--text);
    font-size:13px;
    font-weight:600;
}

.woocommerce-checkout label .required{
    color:#D9534F;
}

.woocommerce-checkout label .optional{
    color:var(--muted);
    font-size:11px;
    font-weight:400;
}

/* INPUTS */
.woocommerce-checkout input.input-text,
.woocommerce-checkout input[type=text],
.woocommerce-checkout input[type=email],
.woocommerce-checkout input[type=tel],
.woocommerce-checkout select,
.woocommerce-checkout textarea{
    width:100%!important;
    box-sizing:border-box;
    height:48px;
    padding:0 14px;
    background:#fff;
    border:1px solid var(--border)!important;
    border-radius:var(--radius)!important;
    color:var(--text);
    font-size:13px;
    outline:0;
    transition:border-color .2s,box-shadow .2s,background .2s;
}

.woocommerce-checkout input:focus,
.woocommerce-checkout select:focus,
.woocommerce-checkout textarea:focus{
    border-color:var(--primary)!important;
    box-shadow:0 0 0 3px rgba(0,102,96,.1);
    background:#fff;
}

/* ORDER REVIEW */
#order_review{
    display:contents;
}

.woocommerce-checkout-review-order-table{
    grid-area:summary;
    width:100%;
    align-self:start;
    padding:24px;
    border-collapse:separate!important;
    border-spacing:0!important;
    margin:0!important;
}

.woocommerce-checkout-review-order-table thead{
    background:transparent;
}

.woocommerce-checkout-review-order-table thead th{
    padding:0 0 18px;
    border:0!important;
    color:var(--primary);
    font-size:17px;
    font-weight:800;
}

.woocommerce-checkout-review-order-table thead th:first-child{
    font-size:0;
}

.woocommerce-checkout-review-order-table thead th:first-child::before{
    content:"☷  خلاصه سفارش";
    font-size:17px;
    color:var(--primary);
}

.woocommerce-checkout-review-order-table thead th:last-child{
    font-size:0;
}

/* PRODUCTS */
.woocommerce-checkout-review-order-table tbody tr{
    border:0!important;
}

.woocommerce-checkout-review-order-table tbody td{
    padding:15px 0;
    border:0!important;
    border-bottom:1px solid #F0F1F2!important;
    vertical-align:middle;
}

.product-name{
    color:var(--text);
    text-align:right;
    font-size:13px;
    font-weight:500;
}

.product-total{
    color:var(--primary);
    text-align:left;
    white-space:nowrap;
    font-size:13px;
    font-weight:700;
}

.product-quantity{
    display:inline-block;
    margin-right:5px;
    color:var(--muted);
    font-size:11px;
    font-weight:500;
}

/* TOTALS */
.woocommerce-checkout-review-order-table tfoot th,
.woocommerce-checkout-review-order-table tfoot td{
    padding:10px 0;
    border:0!important;
    font-size:13px;
}

.cart-subtotal th{
    color:var(--muted);
    font-weight:500;
}

.cart-subtotal td{
    color:var(--text);
    font-weight:700;
}

.order-total{
    margin-top:10px;
    background:var(--primary-soft);
}

.order-total th,
.order-total td{
    padding:16px 14px!important;
}

.order-total th{
    color:var(--primary);
    border-radius:0 8px 8px 0!important;
    font-size:14px;
    font-weight:800;
}

.order-total td{
    color:var(--primary);
    border-radius:8px 0 0 8px!important;
    font-size:20px;
    font-weight:900;
    text-align:left!important;
}

/* PAYMENT */
#payment{
    grid-column:2;
    grid-row:2;
    width:100%;
    margin:0!important;
    padding:28px!important;
}

#payment ul.payment_methods{
    padding:0!important;
    margin:0!important;
    border:0!important;
    list-style:none;
}

#payment ul.payment_methods>li{
    margin:0 0 12px;
    padding:17px;
    background:#fff;
    border:1px solid var(--border);
    border-radius:var(--radius);
    transition:.2s;
}

#payment ul.payment_methods>li:has(input[type=radio]:checked){
    border:2px solid var(--yellow);
    background:var(--yellow-soft);
}

#payment input[type=radio]{
    accent-color:var(--primary);
    margin-left:8px;
}

/* MESSAGES */
#payment .woocommerce-info{
    margin:0;
    padding:14px;
    background:#F7F8F9;
    border:0!important;
    border-radius:var(--radius);
    color:var(--muted);
    font-size:12px;
    line-height:2;
}

/* PRIVACY / TERMS */
.woocommerce-privacy-policy-text{
    margin:18px 0 12px;
    color:var(--muted);
    font-size:11px;
    line-height:2;
}

.woocommerce-privacy-policy-text a,
.woocommerce-terms-and-conditions-checkbox-text a{
    color:var(--primary);
    font-weight:700;
    text-decoration:none;
}

.woocommerce-form__label-for-checkbox{
    display:flex!important;
    align-items:flex-start;
    gap:9px;
    margin:12px 0 0;
    padding:13px;
    background:#F8F9FA;
    border-radius:var(--radius);
    cursor:pointer;
    line-height:1.8;
}

.woocommerce-form__input-checkbox{
    width:18px!important;
    height:18px!important;
    min-width:18px;
    margin:2px 0 0!important;
    accent-color:var(--primary);
}

.woocommerce-terms-and-conditions-checkbox-text{
    color:var(--text);
    font-size:12px;
    font-weight:500;
}

/* PLACE ORDER */
#place_order{
    width:100%!important;
    height:56px;
    margin-top:18px;
    padding:0 20px;
    border:0!important;
    border-radius:var(--radius);
    background:var(--primary)!important;
    color:#fff!important;
    font-size:14px;
    font-weight:800;
    cursor:pointer;
    transition:background .2s,transform .2s,box-shadow .2s;
}

#place_order:hover{
    background:var(--primary-dark)!important;
    transform:translateY(-2px);
    box-shadow:0 8px 20px rgba(23,42,58,.18);
}

#place_order::after{
    content:"←";
    display:inline-block;
    margin-right:9px;
    font-size:17px;
    transition:transform .2s;
}

#place_order:hover::after{
    transform:translateX(-4px);
}

/* PRICE */
.woocommerce-Price-amount{
    direction:ltr;
    unicode-bidi:plaintext;
    display:inline-block;
}

.woocommerce-Price-currencySymbol{
    margin-right:4px;
    font-size:10px;
}

/* REMOVE WC BORDERS */
.woocommerce-checkout table,
.woocommerce-checkout td,
.woocommerce-checkout th{
    border:0!important;
}

/* MOBILE */
@media(max-width:767px){
    form.checkout.woocommerce-checkout{
        display:flex;
        flex-direction:column;
        gap:16px;
        margin:20px 12px;
    }

    #customer_details{order:1}

    .woocommerce-checkout-review-order-table{order:2}

    #payment{
        order:3;
        grid-column:auto;
        grid-row:auto;
    }

    .woocommerce-billing-fields,
    #payment,
    .woocommerce-checkout-review-order-table{
        padding:20px;
    }

    .woocommerce-billing-fields__field-wrapper{
        grid-template-columns:1fr;
        gap:14px;
    }

    .woocommerce-billing-fields__field-wrapper .form-row-wide{
        grid-column:auto;
    }
}

@media(max-width:480px){
    form.checkout.woocommerce-checkout{
        margin:14px 10px;
    }

    .woocommerce-billing-fields,
    #payment,
    .woocommerce-checkout-review-order-table{
        padding:17px!important;
        border-radius:8px;
    }

    .order-total td{
        font-size:17px;
    }

    #place_order{
        height:54px;
    }
}

/* کاهش یک درجه ضخامت نوشته‌ها */

.checkout-titles h3{
    font-weight:700;
}

.woocommerce-checkout label{
    font-weight:500;
}

.woocommerce-checkout label .optional{
    font-weight:400;
}

.woocommerce-checkout-review-order-table thead th{
    font-weight:700;
}

.product-name{
    font-weight:400;
}

.product-total{
    font-weight:600;
}

.product-quantity{
    font-weight:400;
}

.cart-subtotal th{
    font-weight:400;
}

.cart-subtotal td{
    font-weight:600;
}

.order-total th{
    font-weight:700;
}

.order-total td{
    font-weight:800;
}

.woocommerce-terms-and-conditions-checkbox-text{
    font-weight:400;
}

#place_order{
    font-weight:700;
}

.woocommerce-privacy-policy-text a,
.woocommerce-terms-and-conditions-checkbox-text a{
    font-weight:600;
}
